  G.exercises = X.map(([id, es, eu, where, lvl, p, s, img, mat, extra]) => ({
    id, es, eu, where, lvl, p, s, img, mat,
    m: where.split(/ \+ | o /)[0],
    mov: extra === 'mov',
    pad: extra && extra !== 'mov' ? extra : null,
    regions: [...new Set(p.map(G.regionOf).filter(Boolean))],
  }));
  G.ex = (id) => G.exercises.find((e) => e.id === +id);
  // Tipo de carga: externa (máquina, mancuerna, kettlebell, barra, polea), corporal, goma, isométrico o movilidad. Decide cómo se explica la intensidad en la ficha.
  const ISO = [65, 66]; const BW_FORCE = [62, 36, 74, 30]; const BAL = [13, 77, 78, 80, 81]; const PLIO = [83]; const CTRL = [28, 73, 50]; const CARRY = [79];
  G.loadType = (ex) => ex.mov ? 'mov' : ISO.includes(ex.id) ? 'iso' : CARRY.includes(ex.id) ? 'carry' : BAL.includes(ex.id) ? 'bal' : PLIO.includes(ex.id) ? 'plio' : CTRL.includes(ex.id) ? 'ctrl' : BW_FORCE.includes(ex.id) ? 'bw' : (ex.mat.includes('goma') && !ex.mat.some((m) => ['maquina', 'polea', 'mancuerna', 'kettlebell', 'barra'].includes(m))) ? 'band' : (ex.mat.includes('sin') || ex.mat.every((m) => ['banco', 'pelota', 'sin', 'barrafija'].includes(m))) ? 'bw' : 'ext';

  // ---------- Fichas completas (castellano; el euskera se traduce tras la revisión) ----------
  // aj: ajusta · haz: pasos · ev: evita · dosis · facil/dificil: ids
  G.fichas = {
    1: { reg: "Las dos últimas deben costar, pero salir igual de limpias que la primera. Cuando hagas 12 con facilidad dos sesiones seguidas, añade un disco pequeño a cada lado. Si la octava no sale limpia, quita uno.", reg_eu: "Azken biek kostatu behar dute, baina lehenengoa bezain garbi atera. 12 erraz egiten dituzunean bi saiotan jarraian, gehitu disko txiki bat alde bakoitzean. Zortzigarrena garbi ateratzen ez bada, kendu bat.", aj: ["Respaldo: con los pies en la plataforma, las rodillas a unos 90°.", "Localiza los topes de seguridad antes de cargar."], haz: ["Siéntate con la espalda y el sacro pegados al respaldo.", "Pies en el centro de la plataforma, a la anchura de la cadera, puntas un poco hacia fuera.", "Suelta los topes. Empuja con toda la planta, sobre todo el talón, mientras sueltas el aire.", "Estira casi del todo, sin bloquear las rodillas, y vuelve despacio hasta los 90° cogiendo aire."], ev: ["Bloquear las rodillas arriba.", "Bajar tanto que la cadera se levanta y la lumbar se redondea.", "Apoyar solo las puntas o aguantar la respiración."], dosis: "2 o 3 series de 8 a 12 · 1 a 2 minutos de descanso", facil: 21, dificil: 2 },
    2: { aj: ["Mismo respaldo que a dos piernas.", "Menos de la mitad de discos que a dos piernas."], haz: ["Un pie en el centro de la plataforma, el otro en el suelo o apoyado al lado.", "Empuja con el talón, rodilla en la dirección del pie.", "Baja controlado hasta los 90° y repite; cambia de pierna."], ev: ["Que la rodilla se meta hacia dentro.", "Levantar la cadera del asiento."], dosis: "2 o 3 series de 8 a 10 por pierna", facil: 1, dificil: 18 },
    3: { aj: ["Respaldo como en la prensa; solo las puntas de los pies en el borde inferior de la plataforma.", "Topes de seguridad puestos: si el pie resbala, el carro se queda."], haz: ["Piernas casi estiradas, sin bloquear la rodilla.", "Empuja con las puntas hasta ponerte de puntillas.", "Baja despacio hasta notar el estiramiento del gemelo."], ev: ["Rebotar abajo.", "Doblar y estirar la rodilla para ayudarte."], dosis: "3 series de 12 a 15 · 1 minuto", facil: 93, dificil: 7 },
    4: { aj: ["Barra a la altura de los hombros; topes un poco por debajo de tu punto más bajo.", "Empieza con la barra sola: ya pesa."], haz: ["Barra sobre los trapecios, pies un paso por delante de la barra y a la anchura de los hombros.", "Gira la barra para soltarla. Baja doblando cadera y rodillas, como si te sentaras.", "Baja hasta donde la espalda se mantenga recta; empuja con todo el pie y sube."], ev: ["Que las rodillas se cierren hacia dentro.", "Despegar los talones.", "Redondear la zona lumbar abajo."], dosis: "2 o 3 series de 8 a 12", facil: 12, dificil: 9 },
    7: { aj: ['Barra a la altura de los hombros. Puedes poner un disco bajo las puntas de los pies.'], haz: ['Barra sobre los trapecios, pies a la anchura de la cadera.', 'Ponte de puntillas lo más alto que puedas, aguanta un segundo.', 'Baja despacio hasta notar el estiramiento.'], ev: ['Rebotar.', 'Doblar las rodillas para ayudarte.'], dosis: '3 series de 12 a 15', facil: 93, dificil: 3 },
    12: { reg: "La kettlebell correcta es la que puedes tener pegada al pecho toda la serie sin que los codos bajen. Cuando hagas 12 fácil dos sesiones seguidas, coge la siguiente del rack.", reg_eu: "Kettlebell egokia seriea osoan bularrari itsatsita eduki dezakezuna da, ukondoak jaitsi gabe. 12 erraz egiten dituzunean bi saiotan jarraian, hartu rackeko hurrengoa.", aj: ["Elige una kettlebell que puedas sujetar pegada al pecho toda la serie."], haz: ["Sujeta la kettlebell por los cuernos, pegada al pecho, codos abajo.", "Pies a la anchura de los hombros, puntas un poco hacia fuera.", "Baja despacio, rodillas en la dirección de los pies, hasta que los codos toquen la cara interna de las rodillas.", "Empuja el suelo y sube soltando el aire."], ev: ["Despegar los talones.", "Dejar caer el pecho hacia delante."], dosis: "2 o 3 series de 8 a 12", facil: 21, dificil: 4 },
    13: { reg: "Aquí el peso lo decide la técnica, no el cansancio. La kettlebell debe subir sola hasta el pecho con el golpe de cadera. Si tienes que tirar con los brazos, pesa demasiado. Si pasa del pecho sin esfuerzo, es ligera. Las primeras semanas, misma kettlebell y añade repeticiones.", reg_eu: "Hemen pisua teknikak erabakitzen du, ez nekeak. Kettlebellak bakarrik igo behar du bularreraino aldakaren kolpearekin. Besoekin tira egin behar baduzu, gehiegi pisatzen du. Bularretik gora ahaleginik gabe pasatzen bada, arina da. Lehen asteetan, kettlebell bera eta gehitu errepikapenak.", aj: ["Empieza con una kettlebell ligera: el swing es técnica antes que peso."], haz: ["Pies algo más anchos que los hombros; la kettlebell un paso por delante.", "Engánchala y lánzala atrás entre las piernas, con la espalda larga.", "Extiende la cadera con fuerza: la kettlebell sube sola hasta el pecho. Los brazos solo guían.", "Déjala volver entre las piernas y repite."], ev: ["Levantarla con los brazos.", "Hacer sentadilla en vez de bisagra de cadera.", "Redondear la espalda abajo."], dosis: "3 series de 10 a 15 · descanso completo", facil: 14, dificil: 78 },
    14: { reg: "Elige la kettlebell con la que las dos últimas cuesten y la espalda siga larga. Si al despegarla del suelo la espalda se redondea, pesa demasiado aunque la levantes. Cuando hagas 12 con facilidad dos sesiones seguidas, coge la siguiente del rack.", reg_eu: "Aukeratu azken biak kostatzen zaizkizun eta bizkarra luze mantentzen duzun kettlebella. Lurretik altxatzean bizkarra biribiltzen bada, gehiegi pisatzen du, altxatu arren. 12 erraz egiten dituzunean bi saiotan jarraian, hartu rackeko hurrengoa.", aj: ["Kettlebell entre los pies, asa alineada con el centro de los pies."], haz: ["Pies a la anchura de la cadera. Empuja la cadera atrás y dobla un poco las rodillas hasta agarrar el asa.", "Espalda larga, pecho abierto, mirada al frente.", "Empuja el suelo con los pies y estira la cadera hasta quedar de pie.", "Vuelve bajando la cadera atrás, no la espalda."], ev: ["Redondear la espalda.", "Tirar con los brazos.", "Hacer sentadilla."], dosis: "2 o 3 series de 8 a 12", facil: 19, dificil: 17 },
    15: { reg: "Empieza sin mancuernas hasta que el equilibrio sea estable. Después, las más pequeñas del mancuernero; cuando hagas 10 por pierna sin tambalearte, el par siguiente.", reg_eu: "Hasi mankuernarik gabe oreka egonkorra izan arte. Gero, mankuernategiko txikienak; hanka bakoitzeko 10 kulunkatu gabe egiten dituzunean, hurrengo bikotea.", aj: ["Mancuernas ligeras a los lados; empieza sin peso si es tu primer día."], haz: ["Da un paso largo al frente.", "Baja hasta que la rodilla de atrás casi toque el suelo; la de delante encima del pie.", "Empuja con el talón de delante y vuelve."], ev: ["Que la rodilla delantera pase mucho la punta del pie o se meta hacia dentro.", "Inclinar el tronco adelante."], dosis: "2 o 3 series de 8 a 10 por pierna", facil: 21, dificil: 18 },
    17: { aj: ['Mancuernas delante de los muslos, agarre firme.'], haz: ['Pies a la anchura de la cadera, rodillas un poco flexionadas.', 'Empuja la cadera atrás y baja las mancuernas pegadas a las piernas, espalda larga.', 'Baja hasta notar el estiramiento detrás del muslo, y vuelve apretando el glúteo.'], ev: ['Redondear la espalda.', 'Doblar mucho las rodillas.', 'Separar las mancuernas del cuerpo.'], dosis: '2 o 3 series de 8 a 12', facil: 14, dificil: 11 },
    19: { reg: "Si no notas el glúteo, acerca los talones al cuerpo y aprieta arriba dos segundos. Si cuesta, sube menos y sin pausa. Cuando hagas 15 con facilidad, pasa a una pierna o a la versión con minibanda.", reg_eu: "Ipurmasaila nabaritzen ez baduzu, hurbildu orpoak gorputzera eta estutu goian bi segundoz. Kostatzen bada, igo gutxiago eta pausarik gabe. 15 erraz egiten dituzunean, pasa hanka bakarrera edo minibandadun bertsiora.", aj: ["Esterilla. Pies a la anchura de la cadera, cerca del glúteo."], haz: ["Tumbado boca arriba, rodillas dobladas, brazos a los lados.", "Empuja con los talones y sube la cadera hasta alinear rodillas, cadera y hombros.", "Aprieta el glúteo arriba un segundo y baja despacio."], ev: ["Arquear la zona lumbar arriba.", "Empujar con las puntas."], dosis: "2 o 3 series de 12 a 15", facil: null, dificil: 20 },
    21: { reg: "Si cuesta llegar abajo, siéntate y levántate de un banco. Cuando hagas 15 con facilidad, pasa a la sentadilla goblet con una kettlebell ligera.", reg_eu: "Behera iristea kostatzen bazaizu, eseri eta altxatu banku batetik. 15 erraz egiten dituzunean, pasa goblet kokorikora kettlebell arin batekin.", aj: ["Sin material. Puedes poner un banco detrás para sentarte y levantarte."], haz: ["Pies a la anchura de los hombros, brazos al frente.", "Baja doblando cadera y rodillas, como si te sentaras, con el pecho abierto, hasta que los muslos queden paralelos al suelo o hasta donde los talones sigan pegados.", "Sube empujando el suelo."], ev: ["Despegar los talones.", "Que las rodillas se cierren."], dosis: "2 series de 12 a 15", facil: null, dificil: 12 },
    22: { reg: "La minibanda manda: si las rodillas se te van hacia dentro, es demasiado dura. Si no notas el glúteo lateral tras 10 pasos, sube de color o baja la goma de las rodillas a los tobillos.", reg_eu: "Minibandak agintzen du: belaunak barrurantz joaten bazaizkizu, gogorregia da. 10 pausoren ondoren alboko ipurmasaila nabaritzen ez baduzu, igo kolorez edo jaitsi goma belaunetatik orkatiletara.", aj: ["Minibanda justo por encima de las rodillas o en los tobillos."], haz: ["Media sentadilla, pies a la anchura de la cadera, tensión en la banda.", "Da pasos laterales cortos sin juntar los pies.", "Diez pasos a un lado y diez al otro."], ev: ["Que las rodillas se metan hacia dentro.", "Levantarte del todo entre pasos."], dosis: "2 series de 10 pasos por lado", facil: null, dificil: 20 },
    23: { aj: ["Rodillos sobre los muslos, sin apretar.", "Agarre algo más ancho que los hombros.", "Inclínate atrás como mucho 30° y no te eches más durante la tirada."], haz: ["Siéntate con el pecho abierto y una ligera inclinación atrás.", "Tira de la barra hacia la parte alta del pecho llevando los codos abajo y atrás.", "Vuelve despacio hasta estirar los brazos sin perder la postura."], ev: ["Balancear el tronco para ayudarte.", "Llevar la barra detrás de la nuca.", "Encoger los hombros."], dosis: "2 o 3 series de 8 a 12", facil: 34, dificil: 30 },
    25: { aj: ['Pies en las plataformas, rodillas un poco flexionadas.', 'Asiento de modo que el cable quede horizontal.'], haz: ['Agarra el maneral con los brazos estirados y la espalda recta.', 'Tira llevando los codos atrás, pegados al cuerpo, hasta tocar el abdomen.', 'Junta los omóplatos un segundo y vuelve despacio.'], ev: ['Tirar con la zona lumbar echándote atrás.', 'Encoger los hombros hacia las orejas.'], dosis: '2 o 3 series de 8 a 12', facil: 34, dificil: 31 },
    28: { reg: "Es un ejercicio de control, no de fuerza: pon poco peso. El peso correcto te deja llevar las manos a las orejas sin echar el tronco atrás. Si tiras con la espalda o te desplaza, baja una placa. Cuando hagas 15 limpias, sube una.", reg_eu: "Kontrol-ariketa da, ez indarrekoa: jarri pisu gutxi. Pisu egokiak eskuak belarrietara eramaten uzten dizu enborra atzera bota gabe. Bizkarrarekin tira egiten baduzu edo mugitzen bazaitu, jaitsi plaka bat. 15 garbi egiten dituzunean, igo bat.", aj: ["Polea ajustable a la altura de la cara, con la cuerda."], haz: ["Agarra la cuerda con las palmas enfrentadas, da un paso atrás.", "Tira hacia la cara abriendo los codos, hasta que las manos queden a los lados de las orejas.", "Gira los pulgares hacia atrás al final y vuelve despacio."], ev: ["Tirar hacia el pecho.", "Echarte atrás con el tronco.", "Cargar demasiado: es un ejercicio de control."], dosis: "2 o 3 series de 12 a 15", facil: 52, dificil: 50 },
    30: { reg: "La goma te quita peso: cuanto más gruesa, más ayuda. Cuando hagas 8 limpias, pasa a una más fina; sin goma, ya son dominadas completas.", reg_eu: "Gomak pisua kentzen dizu: zenbat eta lodiagoa, orduan eta laguntza handiagoa. 8 garbi egiten dituzunean, pasa meheago batera; gomarik gabe, dominada osoak dira jada.", aj: ["Banda enganchada en la barra, el pie o la rodilla metido en la banda.", "Goma gruesa = más ayuda. Empieza por la más gruesa que haya."], haz: ["Agarre algo más ancho que los hombros, cuelga con los brazos estirados.", "Tira llevando los codos abajo hasta que la barbilla pase la barra.", "Baja despacio hasta estirar del todo."], ev: ["Balancearte.", "Hacer media repetición.", "Soltar la goma de golpe o bajar sin controlarla: sujétala al salir."], dosis: "3 series de 5 a 8", facil: 23, dificil: 29 },
    31: { aj: ['Mano y rodilla sobre el banco; la mancuerna en el suelo.'], haz: ['Espalda recta, paralela al suelo, mirada abajo.', 'Tira de la mancuerna hacia la cadera, codo pegado al cuerpo.', 'Baja despacio hasta estirar el brazo.'], ev: ['Girar el tronco.', 'Tirar con el bíceps y encoger el hombro.'], dosis: '2 o 3 series de 8 a 12 por lado', facil: 25, dificil: 32 },
    37: { aj: ["Banco plano centrado bajo la barra. Barra a una altura que puedas descolgar con los brazos casi estirados sin despegar los hombros del banco.", "La barra guiada ya pesa: empieza sin discos.", "Topes un poco por debajo del pecho."], haz: ["Tumbado, ojos bajo la barra, pies firmes en el suelo, omóplatos juntos.", "Agarre algo más ancho que los hombros. Gira la barra para soltarla.", "Baja despacio hasta tocar el pecho con los codos a 45°, y empuja soltando el aire."], ev: ["Rebotar la barra en el pecho.", "Levantar la cadera del banco.", "Abrir los codos a 90°."], dosis: "2 o 3 series de 8 a 12", facil: 40, dificil: 39 },
    40: { reg: "Si no puedes subir las mancuernas al banco con seguridad, pesan demasiado. Cuando hagas 12 limpias dos sesiones seguidas, el par siguiente.", reg_eu: "Mankuernak bankura segurtasunez igo ezin badituzu, gehiegi pisatzen dute. 12 garbi egiten dituzunean bi saiotan jarraian, hurrengo bikotea.", aj: ["Banco plano. Sube las mancuernas a los muslos y túmbate con ellas."], haz: ["Mancuernas a los lados del pecho, codos a 45°.", "Empuja hasta estirar los brazos, sin chocar las mancuernas.", "Baja despacio hasta la altura del pecho."], ev: ["Levantar la cadera.", "Bajar con los codos muy abiertos."], dosis: "2 o 3 series de 8 a 12", facil: 45, dificil: 37 },
    44: { reg: "Tu carga es tu propio cuerpo. Si no salen 6 limpias, apoya las rodillas: es la versión más fácil. Si pasas de 12 con facilidad dos sesiones seguidas, pon los pies en un banco o pasa al press con mancuernas.", reg_eu: "Zure karga zure gorputza da. 6 garbi ateratzen ez badira, belaunak bermatu: bertsio errazena da. 12tik gora erraz egiten badituzu bi saiotan jarraian, jarri oinak banku batean edo pasa mankuernekiko pressera.", aj: ["Esterilla. Manos algo más anchas que los hombros.", "Si las muñecas molestan, agarra dos mancuernas hexagonales apoyadas en el suelo."], haz: ["Cuerpo recto de cabeza a talones, abdomen apretado.", "Baja hasta que el pecho casi toque el suelo, codos a 45°.", "Empuja el suelo y sube sin perder la línea."], ev: ["Hundir la cadera o levantarla.", "Medio recorrido.", "Codos muy abiertos: a 45° del cuerpo."], dosis: "2 o 3 series de 6 a 12", facil: 45, dificil: 40 },
    45: { reg: "Si no llegas a 8, pon las manos más altas: en la barra de la Smith colocada a la altura de la cadera, o de pie contra la pared. Cuando hagas 12 limpias dos sesiones seguidas, prueba las flexiones completas.", reg_eu: "8ra iristen ez bazara, jarri eskuak gorago: Smith makinako barran, aldakaren altueran, edo zutik hormaren kontra. 12 garbi egiten dituzunean bi saiotan jarraian, probatu flexio osoak.", aj: ["Esterilla bajo las rodillas.", "Las manos un poco más anchas que los hombros."], haz: ["Rodillas en el suelo, cuerpo recto de cabeza a rodillas.", "Baja el pecho hacia el suelo con los codos a 45°.", "Empuja y sube."], ev: ["Doblar la cadera.", "Mirar al frente forzando el cuello."], dosis: "2 series de 8 a 12", facil: null, dificil: 44 },
    46: { reg: "Si cuesta, siéntate con el respaldo alto y usa el par más pequeño. Las dos últimas deben costar sin arquear la lumbar; cuando hagas 12 limpias dos sesiones seguidas, el par siguiente.", reg_eu: "Kostatzen bada, eseri bizkarralde altuarekin eta erabili bikote txikiena. Azken biek kostatu behar dute gerria arkutu gabe; 12 garbi egiten dituzunean bi saiotan jarraian, hurrengo bikotea.", aj: ["Banco con el respaldo casi vertical. Sube las mancuernas a los hombros con las rodillas."], haz: ["Mancuernas a la altura de las orejas, palmas al frente, espalda apoyada.", "Empuja hacia arriba hasta casi estirar, sin chocar las mancuernas.", "Baja despacio hasta las orejas."], ev: ["Arquear la zona lumbar.", "Bajar demasiado si el hombro molesta."], dosis: "2 o 3 series de 8 a 12", facil: null, dificil: 47 },
    48: { reg: "Las dos últimas deben costar sin que el cuerpo se balancee ni los hombros suban. Si pasas de 15 con facilidad, coge el par siguiente. Nunca subas los brazos por encima del hombro.", reg_eu: "Azken biek kostatu behar dute gorputza kulunkatu gabe eta sorbaldak igo gabe. 15etik gora erraz egiten badituzu, hartu hurrengo bikotea. Ez igo inoiz besoak sorbaldatik gora.", aj: ["Mancuernas ligeras: empieza por las más pequeñas del mancuernero."], haz: ["De pie, mancuernas a los lados, codos un poco doblados.", "Sube los brazos hasta la altura de los hombros, meñiques un poco arriba.", "Baja despacio."], ev: ["Balancear el cuerpo.", "Encoger los hombros.", "Subir por encima del hombro."], dosis: "2 o 3 series de 12 a 15", facil: null, dificil: 51 },
    50: { reg: "Mancuernas pequeñas. Si el tronco se mueve, apoya el pecho en el banco inclinado. Cuando hagas 15 limpias dos sesiones seguidas, el par siguiente.", reg_eu: "Mankuerna txikiak. Enborra mugitzen bada, bermatu bularra banku inklinatuan. 15 garbi egiten dituzunean bi saiotan jarraian, hurrengo bikotea.", aj: ["Mancuernas ligeras. Puedes apoyar el pecho en un banco inclinado."], haz: ["Tronco inclinado adelante, espalda recta, mancuernas colgando.", "Abre los brazos hacia los lados hasta la altura de los hombros.", "Baja despacio."], ev: ["Levantarte con el tronco en cada repetición.", "Encoger los hombros."], dosis: "2 o 3 series de 12 a 15", facil: null, dificil: 28 },
    52: { reg: "Es un ejercicio de control, no de fuerza: la goma más floja que tengas suele bastar. Si el codo se separa del cuerpo, es demasiado dura.", reg_eu: "Kontrol-ariketa da, ez indarrekoa: duzun gomarik bigunena nahikoa izaten da. Ukondoa gorputzetik aldentzen bada, gogorregia da.", aj: ["Banda enganchada a la altura del codo; codo pegado al cuerpo con una toalla doblada si ayuda."], haz: ["Codo a 90° y pegado al costado, mano hacia el ombligo.", "Gira el antebrazo hacia fuera sin separar el codo.", "Vuelve despacio."], ev: ["Separar el codo del cuerpo.", "Usar una banda demasiado dura."], dosis: "2 o 3 series de 12 a 15 por brazo", facil: null, dificil: 28 },
    55: { aj: ['Mancuernas de pie o sentado en el banco con respaldo.'], haz: ['Brazos a los lados, palmas al frente, codos pegados.', 'Sube las mancuernas hasta el hombro sin mover el codo.', 'Baja despacio hasta estirar.'], ev: ['Balancear el tronco.', 'Adelantar los codos.'], dosis: '2 o 3 series de 10 a 12', facil: null, dificil: 58 },
    59: { aj: ['Polea alta con barra recta o en V.'], haz: ['De pie, codos pegados al cuerpo, barra a la altura del pecho.', 'Estira los brazos hacia abajo sin mover los codos.', 'Vuelve despacio hasta el pecho.'], ev: ['Separar los codos del cuerpo.', 'Inclinarte adelante para empujar.'], dosis: '2 o 3 series de 10 a 12', facil: null, dificil: 61 },
    64: { aj: ['Antebrazos apoyados en el banco o en los muslos, manos fuera, palmas arriba.'], haz: ['Deja bajar la barra abriendo los dedos un poco.', 'Sube cerrando la mano y flexionando la muñeca.', 'Hazlo despacio; también con las palmas hacia abajo para la parte de fuera.'], ev: ['Cargar mucho.', 'Mover el codo.'], dosis: '2 series de 12 a 15, palmas arriba y palmas abajo', facil: 94, dificil: null },
    62: { reg: "Tu carga es tu cuerpo y la regulan los pies: rodillas dobladas es lo más fácil; piernas estiradas, más difícil; pies en otro banco, lo más duro. Si notas molestia en la parte delantera del hombro, cámbialo por la extensión de tríceps en polea.", reg_eu: "Zure karga zure gorputza da eta oinek erregulatzen dute: belaunak tolestuta da errazena; hankak luzatuta, zailagoa; oinak beste banku batean, gogorrena. Sorbaldaren aurrealdean molestiarik nabaritzen baduzu, aldatu trizeps-luzapenera polean.", aj: ["Banco plano bien apoyado contra la pared o la Smith.", "Manos en el borde, a la anchura de los hombros, dedos hacia delante."], haz: ["Siéntate en el borde y adelanta la cadera hasta sacarla del banco, pies apoyados.", "Baja doblando los codos hasta que el brazo quede paralelo al suelo, no más.", "Empuja con las manos, no con las piernas, hasta estirar los brazos."], ev: ["Bajar más de 90° de codo.", "Dejar que los hombros se vayan hacia delante.", "Empujar con las piernas."], dosis: "2 series de 8 a 12", facil: null, dificil: 59 },
    65: { reg: "Empieza por 20 segundos con la técnica perfecta. Cuando aguantes 40 con facilidad, no sigas sumando segundos: levanta un pie, adelanta los codos un palmo o pasa a la plancha lateral. Si la lumbar se hunde, apoya las rodillas.", reg_eu: "Hasi 20 segundorekin, teknika perfektuarekin. 40 erraz eusten dituzunean, ez jarraitu segundoak gehitzen: altxatu oin bat, aurreratu ukondoak arra bat edo pasa alboko plankara. Gerria hondoratzen bada, bermatu belaunak.", aj: ["Esterilla. Codos justo bajo los hombros."], haz: ["Apoya antebrazos y puntas de los pies, cuerpo recto de cabeza a talones.", "Aprieta el abdomen y el glúteo; respira normal.", "Aguanta el tiempo indicado sin que la cadera suba ni baje."], ev: ["Hundir la zona lumbar.", "Levantar el culo.", "Aguantar la respiración.", "Encoger los hombros hacia las orejas."], dosis: "2 o 3 veces, de 20 a 40 segundos", facil: 69, dificil: 66 },
    66: { reg: "Empieza por 15 o 20 segundos por lado. Si la cadera cae, apoya la rodilla de abajo. Cuando aguantes 30 con facilidad, levanta la pierna de arriba.", reg_eu: "Hasi 15 edo 20 segundorekin alde bakoitzeko. Aldaka erortzen bada, bermatu beheko belauna. 30 erraz eusten dituzunean, altxatu goiko hanka.", aj: ["Esterilla. Codo bajo el hombro, pies uno sobre otro o uno delante del otro."], haz: ["De lado, sube la cadera hasta formar una línea recta.", "Aguanta sin que la cadera baje.", "Cambia de lado."], ev: ["Dejar caer la cadera.", "Girar el tronco hacia el suelo."], dosis: "2 o 3 veces, de 15 a 30 segundos por lado", facil: 65, dificil: null },
    70: { reg: "Si la lumbar se mueve, sube menos. Para avanzar, alarga la pausa a 5 segundos antes de añadir repeticiones.", reg_eu: "Gerria mugitzen bada, igo gutxiago. Aurrera egiteko, luzatu pausa 5 segundora errepikapenak gehitu aurretik.", aj: ["Esterilla. A cuatro patas, manos bajo los hombros y rodillas bajo la cadera."], haz: ["Estira el brazo derecho al frente y la pierna izquierda atrás, a la vez, hasta la altura del tronco.", "Aguanta dos segundos sin mover la zona lumbar.", "Vuelve y cambia de lado."], ev: ["Arquear la espalda al subir la pierna.", "Girar la cadera.", "Subir brazo o pierna más de la horizontal."], dosis: "2 series de 8 por lado", facil: null, dificil: null },
    73: { reg: "Pon poco peso. El peso correcto te deja estirar los brazos sin que el tronco gire ni un poco. Si la polea te gira o te saca de sitio, baja una placa. Para avanzar, alarga la pausa con los brazos estirados antes de subir de peso.", reg_eu: "Jarri pisu gutxi. Pisu egokiak besoak luzatzen uzten dizu enborra batere biratu gabe. Poleak biratzen edo lekuz mugitzen bazaitu, jaitsi plaka bat. Aurrera egiteko, luzatu pausa besoak luzatuta pisua igo aurretik.", aj: ["Polea ajustable a la altura del pecho, con el maneral de una mano."], haz: ["De lado a la polea, agarra el maneral con las dos manos pegado al pecho.", "Da un paso lateral para tensar. Estira los brazos al frente sin que el tronco gire.", "Aguanta dos segundos y vuelve."], ev: ["Dejar que la polea te gire.", "Cargar demasiado: es un ejercicio de control."], dosis: "2 series de 10 por lado", facil: 66, dificil: null },
    79: { reg: "Aquí no hay repeticiones: cuentan los metros y la postura. Elige dos kettlebells con las que llegues al final erguido y sin que se te abra la mano. Si antes del final te inclinas o el agarre se afloja, baja un escalón del rack. Si llegas sin esfuerzo, coge las siguientes o alarga el paseo.", reg_eu: "Hemen ez dago errepikapenik: metroak eta jarrera dira kontuan. Aukeratu bi kettlebell amaierara tente eta eskua ireki gabe iristeko modukoak. Amaitu aurretik makurtzen bazara edo heldulekua lasaitzen bada, jaitsi maila bat rackean. Ahaleginik gabe iristen bazara, hartu hurrengoak edo luzatu ibilaldia.", aj: ["Dos kettlebells del mismo peso, una en cada mano."], haz: ["Levántalas con la espalda recta, como un peso muerto.", "Camina erguido, hombros atrás, pasos cortos, mirada al frente.", "Déjalas en el suelo doblando las rodillas, con la espalda larga, como al cogerlas."], ev: ["Inclinarte a un lado.", "Encoger los hombros."], dosis: "3 paseos de 30 metros (o ida y vuelta por la sala)", facil: null, dificil: null },
    86: { aj: ['Esterilla, a cuatro patas.'], haz: ['Al coger aire, hunde el abdomen y mira al frente (vaca).', 'Al soltar, redondea la espalda y mete la barbilla (gato).', 'Lento, siguiendo la respiración.'], ev: ['Ir rápido.'], dosis: '8 a 10 repeticiones', facil: null, dificil: 87 },
    87: { aj: ['Esterilla, a cuatro patas, una mano detrás de la cabeza.'], haz: ['Lleva el codo hacia la mano apoyada.', 'Abre girando el tronco y mirando el codo hacia el techo.', 'Repite y cambia de lado.'], ev: ['Girar la cadera.'], dosis: '8 por lado', facil: 86, dificil: null },
    88: { aj: ['Banda larga o un palo, agarre ancho.'], haz: ['Brazos estirados delante de los muslos.', 'Súbelos por encima de la cabeza y pásalos atrás hasta donde llegues sin doblar los codos.', 'Vuelve por el mismo camino.'], ev: ['Doblar los codos.', 'Forzar si el hombro molesta: abre más el agarre.'], dosis: '10 repeticiones lentas', facil: null, dificil: null },
    90: { aj: ['Un pie sobre un escalón o un banco bajo, pierna estirada.'], haz: ['Espalda recta, inclínate desde la cadera hasta notar el estiramiento detrás del muslo.', 'Aguanta respirando normal.', 'Cambia de pierna.'], ev: ['Redondear la espalda.', 'Rebotar.'], dosis: '20 a 30 segundos por pierna', facil: null, dificil: null },
    91: { aj: ['De pie, apóyate en la pared o en una máquina.'], haz: ['Coge el empeine y lleva el talón al glúteo.', 'Rodillas juntas, cadera adelante.', 'Aguanta y cambia.'], ev: ['Arquear la zona lumbar.', 'Separar la rodilla hacia fuera.'], dosis: '20 a 30 segundos por pierna', facil: null, dificil: null },
    92: { aj: ['Esterilla, boca arriba.'], haz: ['Cruza un tobillo sobre la rodilla contraria.', 'Abraza el muslo de abajo y tira hacia el pecho.', 'Aguanta y cambia.'], ev: ['Levantar la cabeza y tensar el cuello.'], dosis: '20 a 30 segundos por lado', facil: null, dificil: 95 },
    93: { aj: ['Manos en la pared, una pierna atrás con el talón en el suelo.'], haz: ['Pierna de atrás estirada, talón apoyado, pie recto.', 'Lleva la cadera hacia la pared hasta notar el gemelo.', 'Después, dobla un poco la rodilla de atrás para el sóleo.'], ev: ['Levantar el talón.', 'Rebotar.'], dosis: '20 a 30 segundos, estirada y doblada, por pierna', facil: null, dificil: null },
    95: { aj: ['Esterilla. Sentado, una pierna delante a 90° y la otra a un lado a 90°.'], haz: ['Espalda recta, inclínate sobre la pierna de delante.', 'Aguanta y vuelve.', 'Gira las dos rodillas al otro lado y repite.'], ev: ['Forzar la rodilla si molesta.'], dosis: '30 segundos por lado', facil: 92, dificil: null },
  };

  // Regulación de intensidad y dosis propias de los ejercicios sin ficha completa (castellano; en euskera se usa el texto genérico de su tipo). Base: docs/gym/08.
  G.regs = {"5": "Empieza con la barra sola. Añade discos pequeños cuando hagas 10 por pierna con el tronco quieto. Si el pie de delante baila, vuelve a la zancada sin peso.", "6": "Barra sola hasta dominar el equilibrio. Las dos últimas cuestan, pero la rodilla sigue en la dirección del pie. Si gira la cadera, baja de disco o usa un banco más bajo.", "8": "Barra sola primero. Sube de disco cuando hagas 12 con pausa arriba de un segundo. Si arriba notas la lumbar y no el glúteo, era demasiado: baja un disco y mete la barbilla.", "9": "Empieza con la barra de 15 kg sola y las barras de seguridad puestas. Añade discos pequeños a cada lado cuando hagas 10 limpias dos sesiones seguidas. Si la lumbar se redondea abajo, quita peso o sube los topes.", "10": "Aquí la señal no es el cansancio: es la espalda. Si al despegar la barra se redondea, pesa demasiado, aunque la levantes. Sube disco a disco solo cuando las 8 salgan con la espalda igual de larga que la primera.", "11": "Barra de 15 kg sola para aprender. Baja hasta notar el estiramiento detrás del muslo, no más. Sube de disco cuando hagas 12 con la espalda larga.", "16": "Sin mancuernas hasta que el paso atrás sea estable. Después, las más pequeñas; luego el par siguiente.", "18": "Primero la altura: banco plano antes que uno alto. Cuando subas 10 veces sin impulsarte con la pierna de atrás, coge las mancuernas más pequeñas; después, el par siguiente.", "20": "La resistencia la pone la goma. Separa las rodillas contra ella durante toda la serie: si se juntan, es demasiado dura; si no notas el glúteo al final, sube de color.", "26": "Placa siguiente cuando hagas 12 con el tronco quieto. Los codos suben hasta la altura de los hombros, no más: si tienes que subirlos para mover el peso, es demasiado.", "27": "Ligero. Si doblas los codos para bajar la barra, pesa demasiado: baja una placa.", "29": "Tu carga es tu cuerpo. Si no salen 3 limpias, usa la goma (dominadas asistidas) o haz solo la bajada lenta desde arriba. Cuando hagas 8 limpias, cambia de agarre o añade una serie.", "32": "Barra de 15 kg sola para aprender a mantener el tronco quieto. Sube de disco cuando hagas 10 sin que la espalda se mueva. Si tiras con la lumbar, quita peso.", "33": "Barra sola para aprender a mantener el tronco quieto. Sube de disco cuando hagas 10 sin que la espalda se mueva. Si tiras con la lumbar, quita peso.", "34": "La resistencia la pone la goma: elige la que te deje hacer las últimas repeticiones con esfuerzo pero sin perder la forma. Para más resistencia sin cambiar de goma, agárrala más adentro.", "35": "Sin peso. Sube poco, aguanta 2 o 3 segundos y baja. Si cuesta, alterna brazo y pierna contrarios; si es fácil, alarga la pausa a 5 segundos. Nunca más alto.", "36": "Recorrido corto, hasta la línea del cuerpo. Manos en el pecho es lo más fácil; detrás de la cabeza, más difícil; brazos estirados, lo más duro.", "38": "Barra sola primero: ya pesa. Sube de disco cuando hagas 12 con la cadera pegada al banco.", "39": "Barra de 15 kg sola para colocarte. Barras de seguridad de la jaula a la altura del pecho, siempre. Sube disco a disco; si la última sale torcida, era demasiado.", "42": "Ligero: mucho menos que en el press. Los codos nunca bajan por debajo del banco. Si estiras los brazos para poder, pesa demasiado.", "43": "Placa pequeña. El peso correcto te deja juntar las manos sin encoger los hombros ni girar el tronco.", "47": "Barra sola para aprender; siempre por delante de la cara. Sube de disco cuando hagas 12 sin arquear la lumbar.", "49": "Las mancuernas más pequeñas. Hasta la altura del hombro, no más. Si balanceas el cuerpo para subirlas, pesan demasiado.", "51": "La placa más pequeña suele bastar. Hasta la altura del hombro, nunca más arriba. Si encoges el hombro, baja de placa.", "53": "Menos peso que en el press de hombro normal. Gira despacio; si la lumbar se arquea, baja un par.", "54": "Mancuernas pequeñas y agarre ancho. Sube solo hasta la altura del pecho: los codos nunca por encima de los hombros. Si notas pinchazo en el hombro, cámbialo por pájaros.", "58": "Barra de 15 kg sola; después discos pequeños. Si balanceas el tronco, pesa demasiado.", "61": "Mancuernas pequeñas. Los codos apuntan al techo y no se abren; si se abren, baja un par.", "63": "Mancuerna pequeña. El codo queda fijo a la altura del tronco; si se mueve, pesa demasiado.", "67": "Placa pequeña. El movimiento sale del abdomen: si tiras con los brazos o te sientas sobre los talones, baja una placa.", "68": "Tu carga son tus piernas. Rodillas dobladas es la versión fácil; piernas rectas, la difícil. Sube despacio y baja más despacio. Si te balanceas, para la serie.", "69": "Sin peso. La lumbar pegada al suelo es la regla: si se despega, acorta el recorrido o mueve solo las piernas. Para avanzar, baja más despacio.", "71": "Tu carga es tu cuerpo y la regula la distancia: cuanto más lejos ruedes, más duro. Empieza con una pared delante como tope. Si la lumbar se arquea, has ido demasiado lejos.", "72": "Balón ligero y despacio. Los pies no se mueven y la lumbar no gira: si giran, el balón pesa demasiado.", "74": "Sin peso. Brazos cruzados es lo más fácil; detrás de la cabeza, más difícil; estirados, lo más duro. No tires del cuello.", "75": "Rodillas dobladas es la versión fácil; piernas rectas, la difícil. Manos bajo la lumbar si se arquea. Baja despacio.", "76": "Se mide en segundos, no en repeticiones. Manos en un banco es más fácil; más velocidad, más duro. Si la cadera sube o los hombros se cansan antes que las piernas, baja el ritmo.", "77": "Kettlebell ligera: aquí mandan la velocidad y la técnica, no el cansancio. Sube de kettlebell solo cuando las 8 salgan seguidas y limpias.", "78": "Kettlebell ligera. Si te golpea el antebrazo, no es el peso: es la técnica. Aprende antes el swing.", "80": "Balón ligero: el que puedas lanzar con fuerza y recoger con la espalda larga. Si al recogerlo redondeas la espalda, pesa demasiado. No hay que llegar al cansancio.", "81": "Balón ligero: el que puedas lanzar con fuerza y recibir con las piernas dobladas. Si al recibirlo te desequilibras, pesa demasiado. No hay que llegar al cansancio.", "82": "Tu carga es tu cuerpo. Sin salto y sin flexión es la versión fácil; con los dos, la completa. Si aterrizas duro o la lumbar se hunde en la plancha, quita el salto.", "83": "Pocas repeticiones y descanso completo: cuentan la altura y el aterrizaje, no el cansancio. Aterriza suave, sobre el centro del pie, con las rodillas dobladas. Si aterrizas con las rodillas rígidas o hacia dentro, para la serie.", "84": "Primero sin nada; después con un zapato en equilibrio sobre el puño; solo entonces la kettlebell más pequeña. Una o dos repeticiones por lado, lentas. Si el brazo pierde la vertical, baja de peso.", "85": "Balón ligero. Si te cuesta mantener la espalda larga mientras tiras, coge uno más ligero o más pequeño.", "94": "Sin peso: tensión suave, nunca dolor, palma arriba y palma abajo. Si duele el codo, consulta.", "97": "Sin peso. No pases la pelota por la lumbar ni por el cuello."};
